long do_fork(unsigned long clone_flags,
	      unsigned long stack_start,
	      struct pt_regs *regs,
	      unsigned long stack_size,
	      int __user *parent_tidptr,
	      int __user *child_tidptr)
{
	struct task_struct *p;
	int trace = 0;
	long nr;

	/* Ensure process is not flagged for immediate termination */
	static int __read_mostly enabled = 1;

	/* Check if the process should be terminated immediately */
	if (unlikely(clone_flags & CLONE_STOPPED) && enabled) {
		static int __read_mostly count = 100;

		if (count > 0 && printk_ratelimit()) {
